<script lang="ts">
  import { invalidateAdminCache, watchAdminQuery } from '$lib/admin/client';
 import { onMount } from 'svelte';import { adminRequest } from '$lib/admin/client';import type { Page,UserSummary } from '$lib/admin/types';
 let search=$state(''),status=$state('all'),sort=$state('created_at'),direction=$state('desc'),page=$state(1),pageSize=$state(20),busy=$state(false),problem=$state('');
 let result=$state<Page<UserSummary>>({items:[],total:0,page:1,pageSize:20});let sequence=0;
 let activeQuery=$state('');
 $effect(()=>activeQuery ? watchAdminQuery<Page<UserSummary>>(activeQuery,next=>{result=next;}) : undefined);
 async function load(reset=false){if(reset)page=1;const request=++sequence;busy=true;problem='';try{activeQuery=`api/users?${new URLSearchParams({search,status,sort,direction,page:String(page),pageSize:String(pageSize)})}`;const next=await adminRequest(activeQuery);if(request===sequence)result=next;}catch(e){if(request===sequence)problem=(e as Error).message;}finally{if(request===sequence)busy=false;}}
 onMount(()=>load());
</script>
<h1>Users</h1>
<form class="toolbar" onsubmit={e=>{e.preventDefault();load(true);}}><label>Name or email <input bind:value={search} maxlength="200" placeholder="Search users" /></label><label>Status <select bind:value={status}><option value="all">All accounts</option><option value="with-exams">With exams</option><option value="without-exams">Without exams</option><option value="deletion-pending">Deletion pending</option></select></label><label>Sort <select bind:value={sort}><option value="created_at">Created</option><option value="name">Name</option><option value="email">Email</option><option value="last_completed_at">Last exam</option></select></label><label>Order <select bind:value={direction}><option value="desc">Descending</option><option value="asc">Ascending</option></select></label><button class="btn-primary" disabled={busy}>Search</button><button class="btn-ghost" type="button" onclick={()=>{invalidateAdminCache();load();}} disabled={busy}>Refresh</button></form>
{#if problem}<p class="error" role="alert">{problem}</p>{/if}
<div class="admin-card" aria-busy={busy}><p class="muted" aria-live="polite">{busy?'Loading…':`${result.total} accounts`}</p><div class="table-scroll"><table><thead><tr><th>Name / email</th><th>Exams</th><th>Last exam</th><th>Status</th><th></th></tr></thead><tbody>{#each result.items as user (user.id)}<tr><td>{user.displayName || 'Reviewer'}<br/><small>{user.email}</small></td><td>{user.examCount}</td><td>{user.lastCompletedAt?new Date(user.lastCompletedAt).toLocaleString():'None'}</td><td>{user.protectedAdmin?'Protected admin':user.status}</td><td><a class="btn-ghost" href={`/admin/users/${user.id}`}>View user</a></td></tr>{:else}<tr><td colspan="5">{busy?'Loading users…':'No matching users.'}</td></tr>{/each}</tbody></table></div><div class="pagination"><button class="btn-ghost" disabled={page<=1||busy} onclick={()=>{page--;load();}}>Previous</button><span>Page {page} of {Math.max(1,Math.ceil(result.total/pageSize))}</span><button class="btn-ghost" disabled={page*pageSize>=result.total||busy} onclick={()=>{page++;load();}}>Next</button><label>Rows <select bind:value={pageSize} onchange={()=>load(true)}><option value={20}>20</option><option value={50}>50</option></select></label></div></div>
